window.DRILLS = {"L5": {"video": "drill_l5", "title": "The Push Back", "tag": "DISAGREEMENT", "nar": ["Time for the drill. This one puts you in a disagreement in front of other people.", "Press Play. The video pauses a few times so you can answer, and it resumes when you're done."], "opts": ["Defend the decision", "Back away from your position", "Ask them to explain what you're missing", "Pause, and separate the disagreement from the person"], "optsAt": [33.85, 36.2, 39.0, 43.4], "beats": [{"t": 0.45, "u": 12.7, "kind": "shift", "text": "You've made the call. Someone you respect strongly disagrees, and they're challenging you in front of other people."}, {"t": 9.3, "u": 18.2, "kind": "notice", "text": "Before you respond: what do you notice? In your body, your thoughts, your urge."}, {"t": 26.0, "u": 31.1, "kind": "reframe", "text": "Pressure changes when another person is involved."}, {"t": 33.85, "u": 48.0, "kind": "options", "text": "Your first move"}, {"t": 55.65, "u": 63.9, "kind": "again", "text": "Same disagreement. This time, respond without defending yourself or abandoning your position."}, {"t": 74.15, "u": 86.4, "kind": "condition", "text": "This week, notice one moment when disagreement makes you want to defend, withdraw or solve it straight away. Catch the urge, then choose."}], "holds": [{"t": 18.2, "resume": 25.6, "key": "notice", "kind": "text", "label": "NOTICE", "q": "What do you notice? In your body, your thoughts, your feelings. What is your urge?"}, {"t": 48.0, "resume": 55.5, "key": "choose", "kind": "choice", "label": "CHOOSE", "q": "What is your first move?"}, {"t": 63.9, "resume": 67.8, "key": "again", "kind": "text", "label": "GO AGAIN", "q": "Respond without defending yourself or abandoning your position. What would you actually say?"}]}};
